def transform(g):
    g=[r[:] for r in g]; h,w=len(g),len(g[0])
    gaps=[]
    for r in range(h):
        for c in range(1,w-1):
            if g[r][c]==0 and g[r][c-1]!=0 and g[r][c-1]==g[r][c+1]:
                g[r][c]=g[r][c-1]; gaps.append((c,g[r][c]))
    for c,v in set(gaps):
        r=min(rr for rr in range(h) if g[rr][c]==v)
        rr=r-1
        while rr>=0 and g[rr][c]==0:
            g[rr][c]=v; rr-=1
    for c in range(w):
        r=h-1
        while r>=0:
            if g[r][c]!=0:
                v=g[r][c]; r2=r
                while r2-1>=0 and g[r2-1][c]==v: r2-=1
                left = c>0 and g[r][c-1]==v
                right = c<w-1 and g[r][c+1]==v
                if not (left or right):
                    rr=r2-1
                    while rr>=0 and g[rr][c]==0:
                        g[rr][c]=v; rr-=1
                r=r2-1
            else: r-=1
    return g
